    const sbmRtn5 = await $c.sbm.executeDynamic(sbmOptions5);
    // TODO Stage2: sbmRtn5 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

// ver
scwin.getDepHistLst = async function(ver) {
    const sbmOptions = {
        id : "sbm_mdsDepHist",
        action : "/depusr.do",
        ref : "",
        target : "mdsDepHist=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

scwin.checkMemberExist = async function() {
    const sbmOptions = {
        id : "sbm_mdsMemberCheck",
        action : "/depusr.do",
        ref : "",
        target : "mdsMemberCheck=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
// tp 1:상위부서 목록 2:히스토리
scwin.schMyDept = function(tp, row) {
    let vDept = '';
    if (tp === 1) {
        vDept = mdsPdept.getCellData(row, "DEP_CD");
    } else {
        vDept = mdsDepHist.getCellData(row, "DEP_CD");
    }
    let tmpVal1;
    for (let i = 0; i <= mdsDepLst.getRowCount(); i++) {
        tmpVal1 = mdsDepLst.getCellData(i, "DEP_CD");
        if (tmpVal1 === vDept) {
            mdsDepLst.setFocusedCell(i, 0);
        }
    }
};

scwin.schDept = function(ver) {
    let tmpVal1;
    let tmpVal2;
};

//	ver 0:신규, 1:수정, 2:삭제
scwin.setDeptInfo = function(ver) {
    scwin.logicTp = ver;
    if (ver === "0") {
        lblStrtDD.style.display = "";
        lblEndDD.style.display = "none";
        if (scwin.isSameDept) {
            txtUpDeptNm.setValue(scwin.tmpUpDepNm);
            txtUpDeptCd.setValue(scwin.tmpUpDepCd);
        } else {
            txtUpDeptNm.setValue(scwin.tmpDepNm);
            txtUpDeptCd.setValue(scwin.tmpDepCd);
        }
        txtChrgIndNm.setValue("");
        txtDutyGrpTpCd.setValue(scwin.tmpDutyGrpTpCd);
        txtSndlocTpCd.setValue(scwin.tmpSndlocTpCd);
        txtKclicUsrTpId.setValue(scwin.tmpKclicUsrTpId);
        txtUpDeptNm.setReadonly(true);
        txtUpDeptCd.setReadonly(true);
        txtDeptNm.setReadonly(false);
        txtDeptCd.setReadonly(false);
        txtDeptNm.setValue("");
        txtDeptCd.setValue("");
    } else if (ver === 1) {
        lblStrtDD.style.display = "";
        lblEndDD.style.display = "none";
        txtUpDeptNm.setValue(scwin.tmpUpDepNm);
        txtUpDeptCd.setValue(scwin.tmpUpDepCd);
        txtDeptNm.setValue(scwin.tmpDepNm);
        txtDeptCd.setValue(scwin.tmpDepCd);
        txtChrgIndNm.setValue(scwin.tmpChrgIndNm);
        txtDutyGrpTpCd.setValue(scwin.tmpDutyGrpTpCd);
        txtSndlocTpCd.setValue(scwin.tmpSndlocTpCd);
        txtKclicUsrTpId.setValue(scwin.tmpKclicUsrTpId);
        txtUpDeptNm.setReadonly(true);
        txtUpDeptCd.setReadonly(false);
        txtDeptNm.setReadonly(false);
        txtDeptCd.setReadonly(false);
    } else {
        lblStrtDD.style.display = "none";
        lblEndDD.style.display = "";
        txtUpDeptNm.setValue(scwin.tmpUpDepNm);
        txtUpDeptCd.setValue(scwin.tmpUpDepCd);
        txtDeptNm.setValue(scwin.tmpDepNm);
        txtDeptCd.setValue(scwin.tmpDepCd);
        txtChrgIndNm.setValue(scwin.tmpChrgIndNm);
        txtDutyGrpTpCd.setValue(scwin.tmpDutyGrpTpCd);
        txtSndlocTpCd.setValue(scwin.tmpSndlocTpCd);
        txtKclicUsrTpId.setValue(scwin.tmpKclicUsrTpId);
        txtUpDeptNm.setReadonly(true);
        txtUpDeptCd.setReadonly(true);
        txtDeptNm.setReadonly(true);
        txtDeptCd.setReadonly(true);
    }
};

scwin.setDefault = function() {
    lblEndDD.style.display = "none";
};

scwin.doDepSave = function() {
    if (scwin.valueCheck()) {
        if (scwin.setSaveDeptInfo()) {
            if (scwin.logicNdeptCheck()) {
                let url = "/depusr.do?method=saveDeptInfo";
                let keyVal = "JSP(I:pInput=mdsDeptSave)";
                trSave.Action = url;
                trSave.KeyName = "toinb_dataid4";
                trSave.KeyValue = keyVal;

                trSave.post();
            }
        } else {
            alert('팀 정보 세팅 오류!');
        }
    }
};

scwin.doHistSave = function() {
    let msg1 = "수정된 사항을 저장하시겠습니까?";
    const msg2 = "\r\n(체크된 Row는 수정과 상관 없이 삭제 됩니다.)";
    if (scwin.isHistChecked()) msg1 = msg1 + msg2;
    if (confirm(msg1)) {
        if (scwin.doDeleteHist()) {
            let url = "/depusr.do?method=saveHistInfo";
            let keyVal = "JSP(I:pInput=mdsDepHist)";
            trSave.Action = url;
            trSave.KeyName = "toinb_dataid4";
            trSave.KeyValue = keyVal;

            trSave.post();
        }
    }
};

// 순서대로 지우면 하나가 지워지면서 밑엣게 위로 올라옴. 그래서 거꾸로 지움
scwin.doDeleteHist = function() {
    for (i = mdsDepHist.getRowCount(); i >= 1; i--) {
        if (mdsDepHist.getCellData(i, "CHK_FLAG") === 1) {
            mdsDepHist.removeRow(i + 1);
        }
    }
    return true;
};

scwin.isHistChecked = function() {
    const isChecked = false;
    return isChecked;
};

scwin.logicNdeptCheck = function() {
    if (scwin.logicTp === "0") {
        if (confirm(txtDeptNm.value + "(" + txtDeptCd.value + ")를 신규생성 하시겠습니까?")) {
            return true;
        } else return false;
    } else if (scwin.logicTp === "1") {
        const old_dep_cd = mdsDeptSave.getCellData(1, "DEP_CD");
        const new_dep_cd = mdsDeptSave.getCellData(1, "NEW_DEP_CD");
        if (old_dep_cd !== new_dep_cd) {
            if (confirm('팀코드가 변경되었습니다. 계속진행하시겠습니까?')) {

            } else {
                return false;
            }
        }
        let msg = "[" + scwin.tmpDepNm + "(" + scwin.tmpDepCd + ")]에서 [" + txtDeptNm.value + "](으)로 변경 하시겠습니까?";
        if (scwin.tmpDepNm === txtDeptNm.value) {
            msg = scwin.tmpDepNm + "(" + scwin.tmpDepCd + ") 정보를 변경 하시겠습니까?";
        }
        if (confirm(msg)) {
            return true;
        } else return false;
    } else if (scwin.logicTp === "2") {
        if (confirm(scwin.tmpDepNm + "(" + scwin.tmpDepCd + ")를 삭제 하시겠습니까?")) {
            return true;
        } else return false;
    }
};

scwin.valueCheck = function() {
    if (meAskDate.Text === "") {
        alert("[시작일/종료일]은 필수입니다.");
        return false;
    }
    if (scwin.tmpDepCd === "" || scwin.tmpDepNm === "") {
        alert("팀코드와 팀명은 필수입니다.");
        return false;
    }
    return true;
};

scwin.setSaveDeptInfo = function() {
    try {
        if (mdsDeptSave.getRowCount() !== 0) {
            mdsDeptSave.setJSON([]);
        }
        mdsDeptSave.insertRow();
        mdsDeptSave.setCellData(1, "DEP_CD", scwin.tmpDepCd);
        mdsDeptSave.setCellData(1, "NEW_DEP_CD", txtDeptCd.value);
        mdsDeptSave.setCellData(1, "UP_DEP_CD", txtUpDeptCd.value);
        mdsDeptSave.setCellData(1, "DEP_NM", txtDeptNm.value);
        mdsDeptSave.setCellData(1, "CHRG_IND_NM", txtChrgIndNm.value);
        mdsDeptSave.setCellData(1, "REMK", txtRemk.Text);
        mdsDeptSave.setCellData(1, "DUTY_GRP_TP_CD", txtDutyGrpTpCd.value);
        mdsDeptSave.setCellData(1, "SNDLOC_TP_CD", txtSndlocTpCd.value);
        mdsDeptSave.setCellData(1, "KCLIC_USR_TP_ID", txtKclicUsrTpId.value);
        mdsDeptSave.setCellData(1, "ASK_DATE", meAskDate.Text);
        mdsDeptSave.setCellData(1, "LOGIC_TP", scwin.logicTp);
        return true;
    } catch (err) {
        alert(err);
        return false;
    }
};

scwin.resetList = function() {

    mdsDepLst.reset();
};

scwin.clearEditTextBox = function() {
    txtUpDeptNm.setValue('');
    txtUpDeptCd.setValue('');
    txtDeptNm.setValue('');
    txtDeptCd.setValue('');
    txtChrgIndNm.setValue('');
    txtDutyGrpTpCd.setValue('');
    txtSndlocTpCd.setValue('');
    txtKclicUsrTpId.setValue('');
};

scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox_01(panel_5);
    scwin.setDefault();
    scwin.setDataSet();
    scwin.getDataSetData();
};
